import java.util.*;
import java.io.*;

public class Main {
    static int[][] shortest = new int[15][15][15][15];
    static int[][] cap = new int[400][400];
    static char[][] scien = new char[20][20];
    static char[][] reac = new char[20][20];
    static int[] dx = {1, 0, -1, 0};
    static int[] dy = {0, 1, 0, -1};
    static int iteration = 3;
    static int[] visited = new int[400];
    static int n, t;
    static int infx, infy;
    static int[][] reach = new int[13][13];
    static int[][] treach = new int[13][13];

    static int getNode(int x, int y) {
        return (x - 1) * n + y - 1;
    }

    static boolean canReach(int sx, int sy, int tx, int ty, int ix, int iy) {
        for (int i = 0; i < reach.length; i++) {
            Arrays.fill(reach[i], 0);
        }
        reach[sx][sy] = 1;
        reach[ix][iy] = 2;
        for (int iterCount = 0; iterCount < 100; iterCount++) {
            expand(1);
            if (reach[tx][ty] == 1) return true;
            expand(2);
            if (reach[tx][ty] == 2) return false;
        }
        return false;
    }

    static void expand(int val) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                treach[i][j] = reach[i][j];
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (treach[i][j] == val) {
                    for (int k = 0; k < 4; k++) {
                        int ni = i + dx[k], nj = j + dy[k];
                        if (ni > 0 && nj > 0 && ni <= n && nj <= n && treach[ni][nj] < val && scien[ni][nj] != 'Y') {
                            reach[ni][nj] = val;
                        }
                    }
                }
            }
        }
    }

    static int augment(int cnode, int dest, int bneck) {
        if (cnode == dest) return bneck;
        if (visited[cnode] == iteration) return 0;
        visited[cnode] = iteration;
        for (int i = 0; i <= dest; i++) {
            if (cap[cnode][i] > 0) {
                int flow = augment(i, dest, Math.min(bneck, cap[cnode][i]));
                if (flow > 0) {
                    cap[cnode][i] -= flow;
                    cap[i][cnode] += flow;
                    return flow;
                }
            }
        }
        return 0;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        for (int i = 0; i < shortest.length; i++) {
            for (int j = 0; j < shortest[i].length; j++) {
                for (int k = 0; k < shortest[i][j].length; k++) {
                    Arrays.fill(shortest[i][j][k], Integer.MAX_VALUE);
                }
            }
        }

        st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                scien[i][j] = line.charAt(j - 1);
                shortest[i][j][i][j] = 0;
                if (scien[i][j] == 'Z') {
                    infx = i;
                    infy = j;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                reac[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 0; k < 4; k++) {
                    int ni = i + dx[k], nj = j + dy[k];
                    if (ni > 0 && ni <= n && nj > 0 && nj <= n) {
                        if (scien[i][j] != 'Y' && scien[ni][nj] != 'Y') {
                            shortest[i][j][ni][nj] = 1;
                        }
                    }
                }
            }
        }

        for (int ki = 1; ki <= n; ki++) {
            for (int kj = 1; kj <= n; kj++) {
                for (int ii = 1; ii <= n; ii++) {
                    for (int ij = 1; ij <= n; ij++) {
                        for (int ji = 1; ji <= n; ji++) {
                            for (int jj = 1; jj <= n; jj++) {
                                int val1 = shortest[ii][ij][ki][kj];
                                int val2 = shortest[ki][kj][ji][jj];
                                if (val1 != Integer.MAX_VALUE && val2 != Integer.MAX_VALUE) {
                                    shortest[ii][ij][ji][jj] = Math.min(shortest[ii][ij][ji][jj], val1 + val2);
                                }
                            }
                        }
                    }
                }
            }
        }

        int src = n * n * 2 + 1;
        int dest = n * n * 2 + 2;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (Character.isDigit(scien[i][j])) {
                    cap[src][getNode(i, j)] = scien[i][j] - '0';
                }
                if (Character.isDigit(reac[i][j])) {
                    cap[n * n + getNode(i, j)][dest] = reac[i][j] - '0';
                }
                if (Character.isDigit(scien[i][j])) {
                    for (int ki = 1; ki <= n; ki++) {
                        for (int kj = 1; kj <= n; kj++) {
                            if (scien[i][j] > '0' && reac[ki][kj] > '0') {
                                if (Character.isDigit(reac[ki][kj]) && shortest[i][j][ki][kj] <= t && canReach(i, j, ki, kj, infx, infy)) {
                                    cap[getNode(i, j)][n * n + getNode(ki, kj)] = 1000;
                                }
                            }
                        }
                    }
                }
            }
        }

        int totalFlow = 0, flowRet;
        while ((flowRet = augment(src, dest, 1000)) > 0) {
            totalFlow += flowRet;
            iteration++;
        }

        System.out.println(totalFlow);
    }
}
